class OrderValidator {

    void validate(Order order) {

        if (order.getAddress() == null)

            throw new IllegalArgumentException("Order " + order.getId() + " is missing a shipping address");

        if (order.getItems().isEmpty())
            throw new IllegalArgumentException("Order " + order.getId() + " has no items");
    }
}

class OrderService {

    void placeOrder(Order order) {

        validator.validate(order);   // checked FIRST — before pricing ever sees this order
        double shipping = pricing.calculateShipping(order);

        double total = discounts.applyDiscounts(order, shipping);
        repository.save(order, total);
    }
}

