class OrderValidator {
public:
    void validate(const Order& order) {

        if (!order.hasAddress())
            throw std::invalid_argument("Order " + order.id() + " is missing a shipping address");

        if (order.items().empty())
            throw std::invalid_argument("Order " + order.id() + " has no items");
    }
};

class OrderService {
public:
    void placeOrder(const Order& order) {

        validator.validate(order);   // checked FIRST, before pricing ever sees this order
        double shipping = pricing.calculateShipping(order);

        double total = discounts.applyDiscounts(order, shipping);
        repository.save(order, total);
    }
};

